/**
 * E10 encryption drill harness (test card t_0a8e0c42 — ADR-007 "Testing contract").
 *
 * Bundled by `tests/e2e/encryption/vite.config.mjs` and loaded by
 * `tests/e2e/e10-encryption.spec.ts` into a REAL Chromium page with REAL
 * IndexedDB + REAL WebCrypto. It exists because the claims under test are
 * BROWSER claims that a Node test double cannot settle:
 *
 *  1. KAT vectors re-verified against Chromium's own WebCrypto (the fixtures
 *     were generated by Node's WebCrypto; a pass in Node alone cannot rule out
 *     an implementation-specific quirk on both sides).
 *  2. IndexedDB transaction lifetime: awaiting a MACROTASK (crypto.subtle)
 *     inside a live readwrite transaction deactivates it on firefox/webkit —
 *     this is what made `applyImport`'s seamed `db.tx` write fail in an
 *     encrypted store (E10-Q6; fixed by staging the seals OUTSIDE the tx,
 *     ADR-007 Decision 4.6). Proving the divergence in a real browser rules
 *     out "fake-indexeddb is stricter than spec".
 *  3. `applyImport` / `restoreSnapshot` against a REAL encrypted store.
 *
 * Test-only seams live here, never in `src/`.
 */

import { fromBase64, toBase64, utf8 } from '../../../src/crypto/bytes';
import { deriveKek, deriveRecoveryKek } from '../../../src/crypto/passphrase';
import { open, seal } from '../../../src/crypto/payload';
import { unwrapDmk, wrapDmk } from '../../../src/crypto/keys';
import { registerVault, vault as appVault } from '../../../src/crypto/vault';
import { enableEncryption } from '../../../src/crypto/service';
import { openForTests } from '../../../src/storage/db';
import type { AppDBImpl } from '../../../src/storage/db';
import { DEFAULT_SETTINGS, isEncryptedRecord } from '../../../src/domain/model';
import type { Task } from '../../../src/domain/model';
import {
  applyImport,
  bindDataSafetyDb,
  buildBackupDocument,
  prepareImport,
  restoreSnapshot,
  serializeBackupDoc,
  takeSnapshot,
} from '../../../src/portability/index';
import { APP_SCHEMA_VERSION } from '../../../src/storage/schema';
import type { ImportError, ImportReport } from '../../../src/portability/types';
import type { Result } from '../../../src/storage/errors';
import type { Tx } from '../../../src/storage/db';

/* ------------------------------------------------------------------ *
 * Pinned KAT fixtures (tests/unit/crypto/kat.test.ts, generated once) *
 * ------------------------------------------------------------------ */

const A_CT_HEX =
  '9d3a084431a7679d5847c5a67e5aadb71cc77b3cb0d92d18f97d04bc11de196dfe54339ec851710704c1796a8071c19ef3038c50218d78c860887e';
const B_PBKDF2_HEX = 'ef177144eec9420cbc1093d2a8b344a92bc506d0d4ec9c028dd19f8324d8c1e6';
const C_HKDF_HEX = 'f96b403d739bb69112d33ddc808301fbd04515fefdd2220bf8d7dd4afdd46d2f';
const D_WRAP_HEX =
  'eb25cbadbb627bd82634204898c3019c5a7e333c8ebb040e6800ca46d3c93c3ebc28cc3c6b271d0d75aea01494c93713';

const KEY_ID = '01ARZ3NDEKTSV4RRFFQ69G5FAV';
/**
 * The list every seeded task references. The APP invariant is that a task's
 * `listId` always resolves (tasks are created from a list context), so the
 * harness store must carry the list row too — an orphan task would be
 * quarantined by ADR-004 Stage B on any restore ("listId: references no
 * accepted list record"), which is a harness artifact, not a product path.
 */
const SEED_LIST_ID = '01ARZ3NDEKTSV4RRFFQ69G5FM1';
const AAD = utf8(`todo-enc/1|task|${KEY_ID}`);
const JSON_PLAINTEXT = JSON.stringify({ title: 'Buy milk', notes: null, tags: [] });
const KEY_BYTES = Uint8Array.from({ length: 32 }, (_, i) => i);
const PINNED_IV = Uint8Array.from({ length: 12 }, (_, i) => 0xa0 + i);
const PINNED_WRAP_IV = Uint8Array.from({ length: 12 }, (_, i) => 0xb0 + i);
const PBKDF2_FIXTURE = {
  v: 1 as const,
  alg: 'PBKDF2-HMAC-SHA-256' as const,
  iters: 600_000,
  salt: toBase64(Uint8Array.from({ length: 16 }, (_, i) => i)),
} as const;
const RECOVERY_SECRET = Uint8Array.from({ length: 32 }, (_, i) => 0x20 + i);
const PASSPHRASE = 'correct horse battery staple';

const hex = (b: ArrayBuffer | Uint8Array): string =>
  [...new Uint8Array(b)].map((x) => x.toString(16).padStart(2, '0')).join('');

async function aesKey(): Promise<CryptoKey> {
  return crypto.subtle.importKey('raw', KEY_BYTES.buffer, 'AES-GCM', true, [
    'encrypt',
    'decrypt',
    'wrapKey',
  ]);
}

export type KatResult = Record<string, { pass: boolean; detail: string }>;

async function runKats(): Promise<KatResult> {
  const out: KatResult = {};
  const record = (name: string, pass: boolean, detail: string): void => {
    out[name] = { pass, detail };
  };

  // A — AES-GCM payload seal
  try {
    const key = await aesKey();
    const sealed = await seal(key, AAD, JSON_PLAINTEXT, PINNED_IV);
    record(
      'A_aes_gcm_seal',
      sealed.iv === toBase64(PINNED_IV) && hex(fromBase64(sealed.ct) as Uint8Array) === A_CT_HEX,
      `iv=${sealed.iv} ct=${hex(fromBase64(sealed.ct) as Uint8Array)}`,
    );
    const ctBytes = new Uint8Array(A_CT_HEX.match(/../gu)!.map((h) => parseInt(h, 16)));
    const round = await open(key, AAD, toBase64(PINNED_IV), toBase64(ctBytes));
    record(
      'A_aes_gcm_open',
      round.ok && round.value === JSON_PLAINTEXT,
      round.ok ? round.value : round.error.code,
    );
  } catch (e) {
    record('A_aes_gcm_seal', false, String(e));
  }

  // B — PBKDF2-HMAC-SHA-256 at the shipped 600k floor
  try {
    const material = await crypto.subtle.importKey(
      'raw',
      utf8(PASSPHRASE).buffer as ArrayBuffer,
      'PBKDF2',
      false,
      ['deriveBits'],
    );
    const bits = await crypto.subtle.deriveBits(
      {
        name: 'PBKDF2',
        hash: 'SHA-256',
        salt: (fromBase64(PBKDF2_FIXTURE.salt) as Uint8Array).buffer as ArrayBuffer,
        iterations: PBKDF2_FIXTURE.iters,
      },
      material,
      256,
    );
    record('B_pbkdf2_600k', hex(bits) === B_PBKDF2_HEX, hex(bits));
    const kek = await deriveKek(PASSPHRASE, PBKDF2_FIXTURE);
    record(
      'B_kek_shape',
      kek.algorithm.name === 'AES-GCM' && !kek.extractable,
      `${kek.algorithm.name} extractable=${String(kek.extractable)}`,
    );
  } catch (e) {
    record('B_pbkdf2_600k', false, String(e));
  }

  // C — HKDF recovery KEK
  try {
    const bits = await crypto.subtle.deriveBits(
      {
        name: 'HKDF',
        hash: 'SHA-256',
        salt: new Uint8Array(0).buffer,
        info: utf8('todo-enc/1/recovery-kek').buffer as ArrayBuffer,
      },
      await crypto.subtle.importKey('raw', RECOVERY_SECRET.buffer, 'HKDF', false, ['deriveBits']),
      256,
    );
    record('C_hkdf_recovery', hex(bits) === C_HKDF_HEX, hex(bits));
    const kek = await deriveRecoveryKek(RECOVERY_SECRET);
    record('C_recovery_kek_shape', kek.algorithm.name === 'AES-GCM', kek.algorithm.name);
  } catch (e) {
    record('C_hkdf_recovery', false, String(e));
  }

  // D — DMK wrap/unwrap + slot binding
  try {
    const dmk = await aesKey();
    const kek = await deriveKek(PASSPHRASE, PBKDF2_FIXTURE);
    const wrap = await wrapDmk(dmk, KEY_ID, kek, 'passphrase', PINNED_WRAP_IV);
    record(
      'D_wrap_pinned',
      wrap.iv === toBase64(PINNED_WRAP_IV) && hex(fromBase64(wrap.ct) as Uint8Array) === D_WRAP_HEX,
      hex(fromBase64(wrap.ct) as Uint8Array),
    );
    const good = await unwrapDmk(wrap, KEY_ID, kek, 'passphrase');
    const transposed = await unwrapDmk(wrap, KEY_ID, kek, 'recovery');
    const otherId = await unwrapDmk(wrap, '01ARZ3NDEKTSV4RRFFQ69G5FAX', kek, 'passphrase');
    record(
      'D_slot_binding',
      good.ok &&
        !transposed.ok &&
        transposed.error.code === 'WRONG_KEY_DOMAIN' &&
        !otherId.ok &&
        otherId.error.code === 'WRONG_KEY_DOMAIN',
      `good=${String(good.ok)} transposed=${transposed.ok ? 'ok' : transposed.error.code} otherId=${
        otherId.ok ? 'ok' : otherId.error.code
      }`,
    );
  } catch (e) {
    record('D_wrap_pinned', false, String(e));
  }

  // E — AAD swap defense + tamper (never a silent partial read)
  try {
    const key = await aesKey();
    const sealed = await seal(key, utf8('todo-enc/1|task|AAA'), JSON_PLAINTEXT, PINNED_IV);
    const right = await open(key, utf8('todo-enc/1|task|AAA'), sealed.iv, sealed.ct);
    const wrongId = await open(key, utf8('todo-enc/1|task|BBB'), sealed.iv, sealed.ct);
    const wrongKind = await open(key, utf8('todo-enc/1|list|AAA'), sealed.iv, sealed.ct);
    const bytes = fromBase64(sealed.ct) as Uint8Array;
    bytes[0] = (bytes[0] as number) ^ 0xff;
    const tampered = await open(key, utf8('todo-enc/1|task|AAA'), sealed.iv, toBase64(bytes));
    record(
      'E_aad_and_tamper',
      right.ok && !wrongId.ok && !wrongKind.ok && !tampered.ok,
      `right=${String(right.ok)} wrongId=${String(wrongId.ok)} wrongKind=${String(
        wrongKind.ok,
      )} tampered=${String(tampered.ok)}`,
    );
  } catch (e) {
    record('E_aad_and_tamper', false, String(e));
  }

  return out;
}

/* ------------------------------------------------------------------ *
 * IndexedDB transaction-lifetime probe                                *
 * ------------------------------------------------------------------ */

export type TxProbe = {
  microtask_survives: boolean;
  macrotask_throws: string | null;
  crypto_subtle_throws: string | null;
  seamed_tx_put_throws: string | null;
};

/**
 * The PRE-FIX `applyImport` pattern: a live `readwrite` transaction over
 * `lists`/`tasks` where the seam's async WebCrypto runs BEFORE the put.
 *
 *  - microtask-only await  -> must survive (spec keeps the tx active)
 *  - setTimeout(0) await   -> spec deactivates the tx
 *  - crypto.subtle await   -> deactivates on firefox/webkit (chromium: survives)
 *  - seamed db.tx put      -> the raw code path the product left behind (E10-Q6)
 */
async function probeTxLifetime(db: AppDBImpl): Promise<TxProbe> {
  async function attempt(
    label: string,
    pause: () => Promise<unknown>,
    seamed: boolean,
  ): Promise<string | null> {
    const run = seamed
      ? await db.tx(['tasks'], 'readwrite', async (t: Tx) => {
          await pause();
          try {
            await t.put('tasks', {
              id: `probe-${label}-row`,
              listId: SEED_LIST_ID,
              title: 'probe',
              notes: null,
              status: 'open',
              priority: 'P3',
              tags: [],
              sortOrder: 'h',
              createdAt: 1,
              updatedAt: 1,
              deletedAt: null,
              deviceId: '01ARZ3NDEKTSV4RRFFQ69G5FAV',
            } as unknown as Task);
            return { ok: true as const, value: undefined };
          } catch (e) {
            return {
              ok: false as const,
              error: { code: `threw:${(e as Error).name}` } as never,
            };
          }
        })
      : await db.txRaw(['tasks'], 'readwrite', async (t) => {
          await pause();
          try {
            await t.put('tasks', {
              id: `probe-raw-${label}`,
              listId: SEED_LIST_ID,
              title: 'probe',
              notes: null,
              status: 'open',
              priority: 'P3',
              tags: [],
              sortOrder: 'h',
              createdAt: 1,
              updatedAt: 1,
              deletedAt: null,
              deviceId: '01ARZ3NDEKTSV4RRFFQ69G5FAV',
            } as unknown as Task);
            return { ok: true as const, value: undefined };
          } catch (e) {
            return {
              ok: false as const,
              error: { code: `threw:${(e as Error).name}` } as never,
            };
          }
        });
    if (run.ok) return null;
    const code = (run.error as { code: string }).code;
    return code.startsWith('threw:') ? code.slice(6) : code;
  }

  const micro = await attempt('micro', () => Promise.resolve(), false);
  const macro = await attempt('macro', () => new Promise<void>((r) => setTimeout(r, 0)), false);
  const cryptoErr = await attempt(
    'crypto',
    () => crypto.subtle.digest('SHA-256', new Uint8Array([1, 2, 3])),
    false,
  );
  return {
    microtask_survives: micro === null,
    macrotask_throws: macro,
    crypto_subtle_throws: cryptoErr,
    seamed_tx_put_throws: null, // filled by the encrypted-store test below
  };
}

/* ------------------------------------------------------------------ *
 * Encrypted-store drill: enable -> import -> restore                  *
 * ------------------------------------------------------------------ */

let db: AppDBImpl | null = null;
/**
 * The session vault. Production wires the SINGLETON (`features/crypto/wiring.ts`
 * calls `vault.attach(db)`), and `portability/snapshots-api` reaches that same
 * singleton through a lazy import — so the drills must too, or snapshot/export
 * code would consult a different (locked) vault than the one holding the keys.
 */
let vault: typeof appVault | null = null;
let clock = 1_700_000_000_000;
const now = (): number => (clock += 1000);

function requireDb(): AppDBImpl {
  if (db === null) throw new Error('harness: call open() first');
  return db;
}

export type EnableResult = { ok: boolean; detail: string; status: string };

/** Minimal valid document for prepareImport, built by the PRODUCTION builder. */
function importDoc(): string {
  const T = 1_700_000_000_000;
  const device = '01ARZ3NDEKTSV4RRFFQ69G5FAV';
  const mk = (id: string, listId: string, title: string): Task =>
    ({
      id,
      listId,
      title,
      notes: null,
      status: 'open',
      priority: 'P3',
      tags: [],
      sortOrder: 'h',
      createdAt: T,
      updatedAt: T,
      deletedAt: null,
      deviceId: device,
    }) as unknown as Task;
  const doc = buildBackupDocument({
    kind: 'export',
    exportedAt: T,
    deviceId: device,
    schemaVersion: APP_SCHEMA_VERSION,
    settings: { ...DEFAULT_SETTINGS, lastBackupAt: T },
    lists: [
      {
        id: SEED_LIST_ID,
        name: 'Personal',
        color: '#336699',
        sortOrder: 'h',
        createdAt: T,
        updatedAt: T,
        deletedAt: null,
        deviceId: device,
      },
      {
        id: '01ARZ3NDEKTSV4RRFFQ69G5FM2',
        name: 'Work',
        color: '#336699',
        sortOrder: 'm',
        createdAt: T,
        updatedAt: T,
        deletedAt: null,
        deviceId: device,
      },
    ],
    tasks: [
      mk('01ARZ3NDEKTSV4RRFFQ69G5FA1', SEED_LIST_ID, 'imported alpha'),
      mk('01ARZ3NDEKTSV4RRFFQ69G5FA2', SEED_LIST_ID, 'imported bravo'),
      mk('01ARZ3NDEKTSV4RRFFQ69G5FA3', '01ARZ3NDEKTSV4RRFFQ69G5FM2', 'imported charlie'),
    ],
    snapshots: [],
    app: { name: 'local-first-todo', version: '0.1.0' },
  });
  return serializeBackupDoc(doc);
}

const harness = {
  ready: true,

  async open(name: string): Promise<{ ok: boolean; error?: string }> {
    const opened = await openForTests({ dbName: name });
    if (!opened.ok) return { ok: false, error: opened.error.code };
    db = opened.value;
    bindDataSafetyDb(db);
    // Seed the list row the drills' tasks reference (app invariant above).
    // Pre-C1 here, so the enable sweep encrypts it exactly like real data.
    const seeded = await db.put('lists', {
      id: SEED_LIST_ID,
      name: 'Personal',
      color: '#336699',
      sortOrder: 'h',
      createdAt: 1_700_000_000_000,
      updatedAt: 1_700_000_000_000,
      deletedAt: null,
      deviceId: db.deviceId,
    });
    if (!seeded.ok) return { ok: false, error: seeded.error.code };
    return { ok: true };
  },

  async runKats(): Promise<KatResult> {
    return runKats();
  },

  async probeTx(): Promise<TxProbe> {
    return probeTxLifetime(requireDb());
  },

  /** Enable C1 for real (unstubbed pre-migration snapshot, real PBKDF2). */
  async enable(): Promise<EnableResult> {
    const handle = requireDb();
    // The SINGLETON, exactly as features/crypto/wiring.ts wires it in the app:
    // portability/snapshots-api resolves this same instance through a lazy
    // import, so a locally-constructed vault would split the key holder from
    // the snapshot/export codec.
    await appVault.attach(handle);
    registerVault(appVault);
    vault = appVault;
    await handle.put('settings', { ...DEFAULT_SETTINGS, lastBackupAt: now() });
    const enabled = await enableEncryption({
      db: handle,
      vault: appVault,
      passphrase: PASSPHRASE,
      passphraseConfirm: PASSPHRASE,
      flowOpenedAt: now() - 5000,
      lostPassphraseAcknowledged: true,
      wantRecoveryKey: false,
      now,
    });
    if (!enabled.ok) {
      return {
        ok: false,
        detail: `${enabled.error.code}: ${enabled.error.message}`,
        status: appVault.status,
      };
    }
    return { ok: true, detail: 'enabled', status: appVault.status };
  },

  /** Seed one plaintext-visible task through the seam (encrypted at rest). */
  async addTask(id: string, title: string): Promise<{ ok: boolean; encAtRest: boolean }> {
    const handle = requireDb();
    const r = await handle.put('tasks', {
      id,
      listId: SEED_LIST_ID,
      title,
      notes: null,
      status: 'open',
      priority: 'P3',
      tags: [],
      sortOrder: 'h',
      createdAt: now(),
      updatedAt: now(),
      deletedAt: null,
      deviceId: handle.deviceId,
    } as unknown as Task);
    if (!r.ok) return { ok: false, encAtRest: false };
    const raw = await handle.readUnfiltered('tasks');
    const row = raw.ok ? raw.value.find((x) => x.id === id) : undefined;
    return { ok: true, encAtRest: row !== undefined && isEncryptedRecord(row) };
  },

  /** LEAK AUDIT: the at-rest bytes of a task must not contain its title. */
  async atRestLeakCheck(id: string): Promise<{ encrypted: boolean; titleLeaked: boolean }> {
    const raw = await requireDb().readUnfiltered('tasks');
    const row = raw.ok ? raw.value.find((x) => x.id === id) : undefined;
    if (row === undefined) return { encrypted: false, titleLeaked: false };
    return {
      encrypted: isEncryptedRecord(row),
      titleLeaked: JSON.stringify(row).includes('Buy oat milk secret'),
    };
  },

  /** Real `prepareImport` + `applyImport` into the ENCRYPTED store. */
  async importIntoEncrypted(): Promise<Result<ImportReport, ImportError>> {
    const handle = requireDb();
    const prepared = await prepareImport(importDoc(), {});
    if (!prepared.ok) return prepared;
    return applyImport(prepared.value, { db: handle, now });
  },

  /** Real `takeSnapshot` + `restoreSnapshot` against the encrypted store. */
  async restoreDrill(): Promise<{
    takeOk: boolean;
    restoreOk: boolean;
    restoreError: string | null;
  }> {
    const handle = requireDb();
    const snap = await takeSnapshot('manual', { db: handle, now });
    if (!snap.ok) return { takeOk: false, restoreOk: false, restoreError: snap.error.code };
    const restored = await restoreSnapshot(snap.value.id, { db: handle, now });
    return {
      takeOk: true,
      restoreOk: restored.ok,
      restoreError: restored.ok ? null : JSON.stringify(restored.error),
    };
  },

  /** How the store looks after everything (rows + crypto status). */
  async summary(): Promise<{ tasks: number; encrypted: number; status: string; titles: string[] }> {
    const handle = requireDb();
    const raw = await handle.readUnfiltered('tasks');
    const rows = raw.ok ? raw.value : [];
    const titles: string[] = [];
    for (const row of rows) {
      if (isEncryptedRecord(row)) {
        titles.push('<ciphertext>');
      } else {
        titles.push(row.title);
      }
    }
    return {
      tasks: rows.length,
      encrypted: rows.filter((r) => isEncryptedRecord(r)).length,
      status: vault === null ? 'none' : vault.status,
      titles,
    };
  },

  /** Fill the seamed-tx probe result from the real encrypted-store attempt. */
  async probeSeamedTx(): Promise<string | null> {
    const handle = requireDb();
    const run = await handle.tx(['tasks'], 'readwrite', async (t) => {
      await crypto.subtle.digest('SHA-256', new Uint8Array([1]));
      try {
        await t.put('tasks', {
          id: '01ARZ3NDEKTSV4RRFFQ69G5FA9',
          listId: SEED_LIST_ID,
          title: 'seamed probe',
          notes: null,
          status: 'open',
          priority: 'P3',
          tags: [],
          sortOrder: 'h',
          createdAt: 1,
          updatedAt: 1,
          deletedAt: null,
          deviceId: '01ARZ3NDEKTSV4RRFFQ69G5FAV',
        } as unknown as Task);
        return { ok: true as const, value: null };
      } catch (e) {
        return { ok: false as const, error: { code: `threw:${(e as Error).name}` } as never };
      }
    });
    if (run.ok) return null;
    const code = (run.error as { code: string }).code;
    return code.startsWith('threw:') ? code.slice(6) : code;
  },

  async close(): Promise<void> {
    if (vault !== null) await vault.lock();
    if (db !== null) db.close();
    db = null;
    vault = null;
  },
};

export type E10Harness = typeof harness;

declare global {
  interface Window {
    __e10: E10Harness;
  }
}

window.__e10 = harness;
